import{_ as p,o as l,c as e,a3 as n,j as s,a}from"./chunks/framework.Dz5Q8p4s.js";const u=JSON.parse('{"title":"VQ-VLA: Improving Vision-Language-Action Models via Scaling Vector-Quantized Action Tokenizers","description":"","frontmatter":{"title":"VQ-VLA: Improving Vision-Language-Action Models via Scaling Vector-Quantized Action Tokenizers","arxiv":"2507.01016","date":"2025-07-01","authors":"Yating Wang, Haoyi Zhu, Mingyu Liu, Jiange Yang, Hao-Shu Fang, Tong He","categories":"cs.RO, cs.CV","topics":"动作 tokenizer, 残差 VQ-VAE, VLA 推理加速","outline":[2,2]},"headers":[],"relativePath":"papers/2507.01016.md","filePath":"papers/2507.01016.md","lastUpdated":null}'),i={name:"papers/2507.01016.md"};function m(r,t,c,h,g,o){return l(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="vq-vla-improving-vision-language-action-models-via-scaling-vector-quantized-action-tokenizers" tabindex="-1">VQ-VLA: Improving Vision-Language-Action Models via Scaling Vector-Quantized Action Tokenizers <a class="header-anchor" href="#vq-vla-improving-vision-language-action-models-via-scaling-vector-quantized-action-tokenizers" aria-label="Permalink to &quot;VQ-VLA: Improving Vision-Language-Action Models via Scaling Vector-Quantized Action Tokenizers&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2507.01016" target="_blank" rel="noreferrer">2507.01016</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-07-01</td></tr><tr><td><strong>作者</strong></td><td>Yating Wang, Haoyi Zhu, Mingyu Liu, Jiange Yang, Hao-Shu Fang, Tong He</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用时序卷积残差 VQ-VAE 在比前人多两个数量级的动作轨迹（含大量仿真合成）上训一个通用动作 tokenizer，替换 OpenVLA 的逐维分桶，一次推理吐 5 步动作，长时程成功率与控制频率同时提升。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文按 arXiv v1 全文撰写（ICCV 2025 接收）。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>OpenVLA 这一类把动作接到语言模型词表上的 VLA，动作表示是最朴素的一种：把每个维度的连续值按训练集 1%/99% 分位数切成 256 个桶，7 维动作就是 7 个 token，一次前向只出一步动作。这带来两个直接后果。一是<strong>速度</strong>，7B 模型逐 token 解码一步动作，本文实测只有 4.16 Hz，做不了任何需要连续跟随的操作。二是<strong>长时程误差累积</strong>，每一步都要重新从当前观测推断，抽纸、开抽屉这类需要连续细粒度位移的任务里，单步策略几乎必然在中途漂走。</p><p>本文要问的是：动作 tokenizer 本身能不能像语言/图像 tokenizer 那样被&quot;规模化&quot;？如果能，它是整条 VLA 流水线里性价比最高的一环——tokenizer 只吃动作序列、不吃图像，训练一个只要单张 A100 跑一周，而它的收益会同时落在成功率、推理速度和长时程能力三处。作者进一步押注了一个具体判断：<strong>动作轨迹的仿真-真实域差远小于视觉的域差</strong>，因此可以用海量仿真动作数据把 tokenizer 喂大。这个判断如果成立，等于给 VLA 打开了一条不需要真机数据的扩容通道。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>逐维分桶（RT-1、RT-2、OpenVLA）的优点是零训练成本、与 LLM 词表天然兼容，缺点是它把动作的时空连续性完全丢掉了：相邻时刻、相邻维度之间的强相关性没有被利用，量化误差在长 chunk 上无法被摊平。FAST 用离散余弦变换压缩动作块，是频域方向的改进。MiniVLA 与 VQ-BeT 一系用残差 VQ-VAE 把动作块量化成少量 token，方向对了，但它们的 tokenizer 通常只在<strong>单任务或单数据集</strong>上训练，编码本覆盖不了别的任务，换个下游任务就得重训。</p><p>另一条线是把动作直接用连续头输出（扩散头、流匹配头），绕开离散化，代价是丢掉与 LLM 自回归框架的兼容性。本文选择留在离散框架内，因此问题就精确地变成：<strong>在保持 next-token 预测接口不变的前提下，如何把量化器做得又准又通用</strong>。前人没有把这件事当作独立的 scaling 问题来做，主要原因大概是缺一个足够大且跨具身的动作语料——而这恰好是作者用仿真数据填的那个洞。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从&quot;OpenVLA 只有 4 Hz&quot;这个具体的部署痛点出发，最自然的想法是 action chunking：一次出多步。但直接让自回归模型连续吐 5 步 × 7 维 = 35 个 token，本文的消融表明会崩（LIBERO-90 从 74.76 掉到 66.53），原因是模型学到了&quot;复制前一步&quot;的捷径，一个 chunk 内的多步动作数值高度雷同。</p><p>于是问题转向：能不能用少量 token 表示一整个 chunk？残差 VQ-VAE 是现成答案。接着要面对&quot;编码本泛化&quot;的问题——如果 tokenizer 只见过 LIBERO 的动作，它对真机 Franka 的轨迹就会有大重构误差。此时一个经验观察起作用了：<strong>动作轨迹是低维、平滑、且几乎不含渲染/纹理信息的模态</strong>，它的分布主要由机械臂运动学与人的操作习惯决定，跨仿真器与跨真机的差异远小于图像。既然如此，仿真数据可以近似当作真数据用，而仿真动作数据是可以近乎无限生成的。最后一步是工程上的：MLP 编码器在大数据上撑不住，换成时序卷积就能吃下更长的依赖。整条链条不需要引用本文自己的任何结论就能走通。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>动作是所有具身模态里最容易压缩的一个：一段 5 帧的末端轨迹几乎总是一条光滑曲线，它的本征维度远低于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">7</span></span></span></span>。分桶离散化浪费了这个结构，于是模型不得不逐步预测；而一个在足够多样的轨迹上训练过的残差 VQ 编码本，可以把这条曲线压成两三个 token，使&quot;预测一段运动&quot;和&quot;预测一个词&quot;在代价上对等。关键在于编码本的覆盖面——它决定了量化误差，而量化误差正是长时程误差累积的源头。既然动作模态的仿真-真实差距小，覆盖面就可以用仿真数据买。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以真机任务&quot;把玩具放进抽屉&quot;为例，走一遍完整链路。</p><ul><li><strong>训练 tokenizer（离线，与视觉无关）</strong>：把 Open X-Embodiment、LIBERO、ManiSkill（消融中还用了 RLBench）的动作序列切成长度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 的块 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7474em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathbf">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">n</span><span class="mbin mtight">×</span><span class="mord mathnormal mtight">d</span></span></span></span></span></span></span></span></span></span></span></span>。输入前先叠两种嵌入：正弦时间嵌入（编码块内时序位置）与可学习的动作类型嵌入（XYZ / 欧拉角 / 夹爪三类语义各一份）。编码器是 2D 时序卷积（替代原残差 VQ-VAE 的 MLP），输出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4444em;"></span><span class="mord mathbf">x</span></span></span></span>，经残差向量量化得到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 层码字，解码器用转置卷积重建。单张 A100、batch 1024，约一周。</li><li><strong>接进 VLA</strong>：冻结 tokenizer，把 OpenVLA 的分桶器换掉。第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 层 VQ 的 token ID 偏移 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">i</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">256</span></span></span></span>，保证不同层的同号码字不会被混淆成同一语义。VLM 用 LoRA 微调，损失是标准的 next-token 交叉熵。</li><li><strong>推理</strong>：给定第三人称 RealSense 图像与指令，VLM 一次自回归吐 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 个动作 token，送进冻结的 VQ 解码器还原成 5 步动作，机器人以 20 Hz 依次执行。实测执行频率 11.84 Hz，相对原版 OpenVLA 的 4.16 Hz 约 2.85 倍。</li><li><strong>真机设定</strong>：Franka Research 3，第三人称固定 RealSense D435，动作定义为 SE(3) 绝对末端位姿；6 个任务（4 短时程 + 2 长时程），每任务 50 条演示、单独微调 100K 步、20 次试验。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>残差向量量化把一个连续向量拆成一串码字的累加。给定编码器输出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4444em;"></span><span class="mord mathbf">x</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">ϕ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">enc</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，令 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5944em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.4444em;"></span><span class="mord mathbf">x</span></span></span></span>，逐层做</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathbf">q</span><span class="mopen">(</span><span class="mord mathbf">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.2143em;vertical-align:-1.2777em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.9367em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.4083em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1645em;"><span style="top:-2.357em;margin-left:-0.109em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2819em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathbf">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathbf">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord">⋅</span><span class="mclose">)</span></span></span></span> 是第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 层码本上的最近邻查找。直觉上这是&quot;逐层修正&quot;：第一层用一个粗码字近似 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4444em;"></span><span class="mord mathbf">x</span></span></span></span>，第二层再量化剩下的残差，以此类推。这比单层 VQ 划算的原因是容量按乘法增长——<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 层各 256 个码字给出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8413em;"></span><span class="mord">25</span><span class="mord"><span class="mord">6</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1645em;"><span style="top:-2.357em;margin-left:-0.109em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2819em;"><span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span> 种组合，而参数量只线性增长。</p><p>训练目标是重建项 + 码本项 + 承诺项：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∥</span><span class="mord"><span class="mord mathbf">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.1141em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7079em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf">a</span></span><span style="top:-3.0134em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord">∥</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathnormal">λ</span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord">∥</span><span class="mord"><span class="mord mathrm" style="margin-right:0.0139em;">sg</span></span><span class="mopen">(</span><span class="mord mathbf">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.1141em;vertical-align:-0.25em;"></span><span class="mord mathbf">q</span><span class="mopen">(</span><span class="mord mathbf">x</span><span class="mclose">)</span><span class="mord"><span class="mord">∥</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∥</span><span class="mord mathbf">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2141em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathrm" style="margin-right:0.0139em;">sg</span></span><span class="mopen">(</span><span class="mord mathbf">q</span><span class="mopen">(</span><span class="mord mathbf">x</span><span class="mclose">))</span><span class="mord"><span class="mord">∥</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm" style="margin-right:0.0139em;">sg</span></span><span class="mopen">(</span><span class="mord">⋅</span><span class="mclose">)</span></span></span></span> 是停止梯度：第二项只更新码本（把码字拉向编码器输出），第三项只更新编码器（防止编码器输出跑离码本，即 commitment）。本文取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span>，这个值偏大，意味着更强调&quot;编码器不要漂&quot;，代价是重建精度让位于码本稳定性。</p><p>接进 VLM 后的损失是普通的条件似然：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">VLM</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.2143em;vertical-align:-1.2777em;"></span><span class="mord">−</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.9367em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.4083em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1645em;"><span style="top:-2.357em;margin-left:-0.109em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2819em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mopen">(</span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8747em;"><span style="top:-2.453em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3831em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2578em;vertical-align:-0.3831em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8747em;"><span style="top:-2.453em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3831em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight">h</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span></span></p><p>这里有一个容易忽略的推论：优化目标是 token 级交叉熵，而部署时关心的是解码后动作的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 误差，两者之间隔着一个非线性解码器。码本层级的偏移设计（第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 层落在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">256</span><span class="mopen">(</span><span class="mord mathnormal">i</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">256</span><span class="mord mathnormal">i</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>）保证了 token 空间的语义可分，但<strong>没有</strong>保证 token 级错误与动作级误差成正比——猜错第一层码字的代价远大于猜错第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 层。本文没有讨论这一点，这是可以推断出的一个结构性隐患。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：卷积编码器是否真的比 MLP 好，tokenizer 能否随数据变强？</strong> 在 LIBERO-10/GOAL 上对比 MLP 与卷积残差 VQ-VAE，并把训练集从单任务扩到全 LIBERO。结论是卷积版更好（LIBERO-10 60.0 vs MLP 53.4，原版 OpenVLA 51.0），且从单任务扩到全 LIBERO 一致提升。注意 LIBERO-GOAL 上卷积版 75.2 略低于原版 OpenVLA 的 75.8，&quot;一致提升&quot;只在数据量这一轴上成立。</p><p><strong>问题二：域外仿真数据能否撑起 tokenizer？</strong> 为避免同域泄漏，作者改用完全域外的 ManiSkill 与 RLBench 训 tokenizer，在 LIBERO-90 上评。结果 VQ$_{M+R}$ 达到 80.98%，比 OpenVLA 基线 73.53% 高 7.45 点。但同一张表里 <strong>只用 ManiSkill 的 VQ$_M$ 只有 14.38%</strong>，几乎完全崩溃。论文把它解释为&quot;合成数据规模不足&quot;，这个解释与文中另一处&quot;ManiSkill 比 LIBERO 大 50 倍&quot;的陈述方向相反——更可能的原因是单一仿真器的动作分布覆盖不了 LIBERO 的运动模式，或那一次训练本身失败。这一格是全文最需要解释而解释得最薄弱的地方。</p><p><strong>问题三：真机上是否成立？</strong> 四个短时程任务平均成功率从基线 23% 升到 46.25%，其中&quot;扶正倒下的锅&quot;从 30% 到 60%；&quot;抽纸&quot;这种要连续细粒度拉拽的任务，基线 5% 近乎全败，加 VQ 后到 20% 以上。两个长时程任务里，&quot;把玩具放进抽屉&quot;表 3 记为基线 5.0 → VQ$_{O+L+M}$ 25.0。<strong>正文与表格不一致</strong>：§4.2.3 称两个长时程任务分别达到 50% 和 30%，且称基线&quot;低至 15% 或接近 0&quot;，而表 3 给出的是 25.0 与 5.0，引用时应以表为准。另外表 2 的 LIBERO-90 基线是 73.53 而表 5 的同设定基线是 74.76，两处对不上。</p>',32),s("p",null,[s("strong",null,"问题四：仿真-真实动作域差有多大？"),a(" 只用 LIBERO 训的 VQ$_L$ 在三个真机任务上得 10.0/55.0/35.0，与 VQ$"),s("em",{"O+L":""},"O$（15.0/45.0/35.0）、VQ$"),a("$（10.0/45.0/35.0）基本同档，作者据此判定域差很小。样本量是 3 个任务 × 20 次，刻度 5%，这个结论的证据强度有限。")],-1),n('<p><strong>问题五：收益来自 chunking 还是来自 VQ？</strong> 作者做了唯一一个直接对照：让 OpenVLA 自回归输出 5 步动作。结果 LIBERO-90 从 74.76 掉到 66.53，真机两个任务掉到 10.0 / 0.0。作者的诊断是自回归 chunk 内出现&quot;复制上一步&quot;的捷径。嵌入消融则很小：加时间/类型嵌入在 LIBERO-90 上只 +0.99（85.17→86.16）。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：VQ-VLA 把 OpenVLA 的逐维分桶换成在超大规模动作语料上训练的时序卷积残差 VQ-VAE，一次推理输出 5 步动作。tokenizer 只吃动作、不吃图像，单卡一周可训，且冻结后可零样本迁移到不同下游任务。作者用完全域外的仿真动作数据把 tokenizer 扩大，LIBERO-90 上从 73.53% 提到 80.98%，真机短时程平均从 23% 提到 46.25%，执行频率从 4.16 Hz 提到 11.84 Hz。他们据此主张动作模态的仿真-真实域差很小，因而 tokenizer 可以靠合成数据扩容。但只用单一仿真器（ManiSkill）训练的版本崩到 14.38%，这与&quot;规模决定一切&quot;的叙事直接冲突，且正文与表格在长时程数字上不一致。</p><p><strong>三句话版</strong>：动作序列比图像更好压缩，因此动作 tokenizer 是 VLA 里最便宜的可扩展部件。用域外仿真轨迹把残差 VQ-VAE 训大，可以同时改善成功率、速度与长时程稳定性。但&quot;数据越多越好&quot;的证据里混着一个反例（单仿真器版本崩溃），真正起作用的可能是分布覆盖面而非数据量。</p><p><strong>一句话版</strong>：把动作块交给一个在海量（大部分是合成的）轨迹上训过的残差 VQ 编码本，VLA 就能一次说完一整段动作。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的是那句被写进摘要的判断：<strong>合成动作轨迹与真实动作轨迹之间的域差可以忽略</strong>。它之所以关键，是因为整篇文章的扩容路线完全建立在它之上——如果不成立，那么&quot;用 ManiSkill 的 120k 条轨迹把 tokenizer 喂大&quot;就不是在扩大有效覆盖，而是在往编码本里塞与部署分布无关的码字。</p><p>它在实践中很可能局部失效，理由有三。第一，tokenizer 是<strong>无条件</strong>训练的（只吃动作序列，不吃观测），所以它学到的是动作块的<strong>边缘分布</strong>；域差小与否只在边缘分布层面被检验过，而下游真正需要的是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathbf">a</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">o</span><span class="mclose">)</span></span></span></span> 的条件支撑集被覆盖。第二，真机动作被定义为 SE(3) 的<strong>绝对</strong>末端位姿（位置 + 四元数），而 OXE / LIBERO / ManiSkill 主流是<strong>增量</strong>位姿加欧拉角；动作类型嵌入是按 XYZ / 欧拉角 / 夹爪三类硬编码的，参数化一换，这份先验就可能失配（此处为基于证据的推断，论文未说明真机是如何对齐到 7 维接口的）。第三，也是最直接的：VQ$_M$ = 14.38% 就是同一条假设失效的实例——ManiSkill 的动作分布单独用时并没有&quot;因为动作域差小&quot;而迁移过去。</p>',8),s("p",null,[a("论文为这条假设提供的正面证据只有一张表：VQ$_L$ 与 VQ$"),s("em",{"O+L":""},"O$、VQ$"),a("$ 在 3 个真机任务上表现相当。这是相关性证据，不是覆盖度证据，而且样本量只有每格 20 次。缺的是最直接的量化：不同 tokenizer 在"),s("strong",null,"留出的真机轨迹"),a("上的重构误差。")],-1),n('<h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、且不需要复现整套 VLA 的方案：只训 tokenizer，只量重构。</p><ul><li><strong>数据</strong>：取任意一个公开真机数据集（例如 DROID 或 Bridge V2 的一个子集）作为留出真机集 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">R</span></span></span></span>；取 ManiSkill / LIBERO 作为合成集 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.075em;">S</span></span></span></span>。</li><li><strong>实现</strong>：按本文架构训 4 个 tokenizer——(a) 只用 OXE，(b) OXE + 10% <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.075em;">S</span></span></span></span>，(c) OXE + 100% <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.075em;">S</span></span></span></span>，(d) 只用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.075em;">S</span></span></span></span>。每个单卡即可。</li><li><strong>测量</strong>：在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">R</span></span></span></span> 上算逐块重构 MSE 与末端位置误差（毫米级），并按&quot;最大位移&quot;分档统计（区分小位移与大位移块）；同时记录码本利用率与 perplexity。</li><li><strong>判据</strong>：如果 (b)→(c) 的重构误差显著下降且 (d) 的误差与 (a) 同档，则&quot;合成动作可扩容&quot;成立；如果 (d) 的误差明显更大、而 (c) 只比 (a) 好一点点，那么本文的增益更可能来自 OXE 那一部分，仿真数据只是没有伤害。若 (d) 误差不大但下游成功率仍崩（对应 VQ$_M$ 那一格），则问题不在 tokenizer 的重构能力，而在下游 token 分布的可学性——这一条本身就是有价值的负结果。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的替代解释是：<strong>全部增益来自 action chunking 这一件事，与量化器的规模与质量几乎无关</strong>。本文唯一的对照（自回归输出 5 步）不足以排除它，因为那个对照同时改变了两件事——既换了 chunk 机制，又保留了会诱发&quot;复制上一步&quot;捷径的自回归解码，作者自己也承认观察到了这个捷径。换句话说，那不是&quot;chunking 无效&quot;的证据，而是&quot;用自回归做 chunking 的这一种实现无效&quot;的证据。</p><p>干净的反例实验：固定 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span> 的 chunk 与完全相同的 LoRA 微调预算，只替换 chunk 的编码方式，跑三组——(i) VQ$_{O+L+M}$；(ii) <strong>朴素分桶 chunk</strong>，即把 5 步 × 7 维直接展平成 35 个分桶 token，用<strong>非自回归</strong>的并行头一次输出（避免捷径）；(iii) FAST 式 DCT 压缩 chunk。同时报告三者在留出集上的<strong>动作重构误差</strong>与 LIBERO-90 成功率。如果 (ii) 与 (i) 在成功率上接近，而重构误差差距很大，那么&quot;tokenizer 越准越好&quot;这条主链就被证伪，真正起作用的只是&quot;一次预测一段&quot;。</p><p>第二个可预测的失败场景：在需要<strong>高频反馈</strong>的接触任务（插孔、擦拭）上，一次固定 5 步的开环 chunk 会系统性劣于单步策略，因为 chunk 执行期间没有视觉反馈。本文的 6 个真机任务全是抓放/开合类，恰好避开了这一档。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>一个非增量的重构方向：<strong>把动作 tokenizer 的训练目标从&quot;重构动作&quot;改成&quot;最小化控制损失下的率失真&quot;</strong>。</p><p>(a) 驱动它的局限：本文的 tokenizer 用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 重构训练，对所有维度、所有时刻一视同仁，但控制任务对误差的敏感度极不均匀——接近接触时的 1 毫米误差与自由空间中的 1 厘米误差后果完全不同。这解释了为什么加时间/类型嵌入只值 +0.99 点，而 tokenizer 训练集换一换就能崩掉 60 点：重构误差不是下游代价的良好代理。</p><p>(b) 可借鉴的相邻领域工具：有损压缩里的<strong>率失真理论</strong>与神经压缩中的&quot;任务导向编码&quot;（task-aware compression）。把码本大小/层数当作码率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span>，把闭环控制代价当作失真 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span></span></span></span>，训练一个以下游策略损失（或一个学习到的 critic 给出的价值下降）为失真度量的编码器。这与 LLM 里 BPE 词表按压缩率而非语义选择合并规则是同一类问题，只是失真度量换成了控制代价。</p><p>(c) 第一个实验长什么样：在 LIBERO 上固定 OpenVLA 骨干，训练两个 tokenizer——一个用标准 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord">ℓ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，一个用&quot;逆动力学一致性&quot;失真（解码后的动作块经过一个预训练的正向模型后，末状态与真值末状态的差），码率预算严格对齐（同样的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 与码本大小）。测三条曲线：重构 MSE、末状态误差、任务成功率。假设是第二个 tokenizer 在重构 MSE 上更差、在末状态误差与成功率上更好；如果成立，就说明动作 tokenizer 应该被当作控制问题而不是压缩问题来设计，也顺带解释了 VQ$_M$ 那一格的崩溃。</p>',12)])])}const y=p(i,[["render",m]]);export{u as __pageData,y as default};
